SELECT JSON_OBJECT('row',JSON_OBJECT(CONVERT(X'636f756e74' USING utf8mb4),COUNT(*))) FROM (SELECT DISTINCT pc.position_id FROM c_position_chain pc WHERE pc.deleted=0 AND pc.industry_chain_id IN (16764,16765,16766,16767,16923,16924,16925,16926,16927,16928,16929,16930,16931,16932,16933,16934,16935,16936,16937,16938,16939,16940,16941,16942,16943,16944,16945,16946,16947,16948,16949,16950,16952,16953,16954,16955,16956,16957,16958,16959,16960,16961,16962,16963,16964,16965,16966,16967,16968,16969,16970,16971,16972,16973,16974,16975,16976,16977,16978,16979,16980,16981,16982,16983,16984,16985,16986,16987,16988,16989,16990,16991,16992,16993,16994,16995,16996,16997,16998,16999,17000,17001,17002,17003,17004,17005,17006,17007,17008,17009,17010,17011,17012,17013,17014,17015,17016,17017,17018,17019,17020,17021)) industry_candidates JOIN c_company_position p ON p.id=industry_candidates.position_id LEFT JOIN c_company_address a ON a.id=p.company_address_id WHERE p.publish_state='PUBLISHING' AND p.deleted=0 AND a.province IN (CONVERT(X'e5b9bfe4b89ce79c81' USING utf8mb4),CONVERT(X'e5b9bfe4b89c' USING utf8mb4));
